/**
 * @fn      zb_zcl_se_metering_send_req_mirror
 * 
 * @brief   Send COMMAND_SE_METERING_REQ_MIRROR command (without payload)
 * 
 * @param   src_ep - source endpoint
 * @param   dst_addr - pointer to destination address
 * @param   disable_default_response - whether to disable default response
 * @param   seq_num - sequence number
 * 
 * @return  zb_status_t
 */

#define zb_zcl_se_metering_send_req_mirror(src_ep, dst_addr, disable_default_response, seq_num) \
    zb_zcl_send_cmd(src_ep, dst_addr, ZCL_CLUSTER_ID_SE_METERING, COMMAND_SE_METERING_REQ_MIRROR, (disable_default_response), (seq_num), 0, NULL)

